// A new buffer is empty, and stays empty after a failed pop.
static void empty_on_construction(){
    RingBuffer<int, 8> rb;
    CHECK(!rb.pop().has_value());
    CHECK(!rb.pop().has_value());
}

static void single_push_pop(){
    RingBuffer<int, 8> rb;
    CHECK(rb.push(42));
    auto v = rb.pop();
    CHECK(v.has_value() && *v == 42);
    CHECK(!rb.pop().has_value());
}

static void fifo_order(){
    RingBuffer<int, 16> rb;
    for (int i = 0; i < 10; ++i)
        CHECK(rb.push(i));
    for (int i = 0; i < 10; ++i){
        auto v = rb.pop();
        CHECK(v.has_value() && *v == i);
    }
    CHECK(!rb.pop().has_value());
}

// One slot stays empty to tell full from empty: usable capacity is buckets - 1.
template <std::size_t buckets>
static void capacity_and_full(){
    RingBuffer<int, buckets> rb;
    constexpr int usable = static_cast<int>(buckets) - 1;

    for (int i = 0; i < usable; ++i)
        CHECK(rb.push(i));
    CHECK(!rb.push(999));              // full
    CHECK(!rb.push(999));              // still full, nothing overwritten

    for (int i = 0; i < usable; ++i){
        auto v = rb.pop();
        CHECK(v.has_value() && *v == i);
    }
    CHECK(!rb.pop().has_value());      // the rejected 999s never got in
}

// After filling, one pop frees exactly one slot.
static void pop_frees_one_slot(){
    RingBuffer<int, 4> rb;
    CHECK(rb.push(1) && rb.push(2) && rb.push(3));
    CHECK(!rb.push(4));
    CHECK(rb.pop() == 1);
    CHECK(rb.push(4));
    CHECK(!rb.push(5));
    CHECK(rb.pop() == 2);
    CHECK(rb.pop() == 3);
    CHECK(rb.pop() == 4);
    CHECK(!rb.pop().has_value());
}

// Indices wrap many times; values come out in order across the wrap.
static void wraparound(){
    RingBuffer<std::uint64_t, 8> rb;
    std::uint64_t next_in = 0, next_out = 0;
    for (int round = 0; round < 1000; ++round){
        const int burst = 1 + round % 7;              // 1..7, up to full
        for (int i = 0; i < burst; ++i)
            CHECK(rb.push(next_in++));
        for (int i = 0; i < burst; ++i){
            auto v = rb.pop();
            CHECK(v.has_value() && *v == next_out);
            ++next_out;
        }
        CHECK(!rb.pop().has_value());
    }
    CHECK(next_in == next_out);
}

// Producer runs ahead of the consumer by a varying amount, never overflowing.
static void interleaved(){
    RingBuffer<int, 32> rb;
    int next_in = 0, next_out = 0, in_flight = 0;
    for (int step = 0; step < 100'000; ++step){
        const int pushes = step % 5, pops = (step * 7) % 5;
        for (int i = 0; i < pushes; ++i){
            const bool ok = rb.push(next_in);
            CHECK(ok == (in_flight < 31));
            if (ok) { ++next_in; ++in_flight; }
        }
        for (int i = 0; i < pops; ++i){
            auto v = rb.pop();
            CHECK(v.has_value() == (in_flight > 0));
            if (v) { CHECK(*v == next_out); ++next_out; --in_flight; }
        }
    }
}

// Smallest legal size: one usable slot.
static void two_buckets(){
    RingBuffer<int, 2> rb;
    for (int i = 0; i < 5; ++i){
        CHECK(rb.push(i));
        CHECK(!rb.push(-1));
        CHECK(rb.pop() == i);
        CHECK(!rb.pop().has_value());
    }
}

// A struct payload comes back field for field.
static void struct_payload(){
    RingBuffer<Tick, 4> rb;
    CHECK(rb.push(Tick{34'200'000'000'000, 1'234'500, 300}));
    CHECK(rb.push(Tick{-1, 0, 0}));
    auto a = rb.pop();
    CHECK(a && a->ts_ns == 34'200'000'000'000 && a->price == 1'234'500 && a->qty == 300);
    auto b = rb.pop();
    CHECK(b && b->ts_ns == -1 && b->price == 0 && b->qty == 0);
}

